/**
 * Core ServiceListFilter Components
 * Provides render props for filter data from ServiceListService and BookingService
 */
import { useService } from '@wix/services-manager-react';
import { ServiceListServiceDefinition } from '../../../services/service-list/service-list.js';
import { BookingServiceDefinition } from '../../../services/booking/booking.js';
/**
 * Core render props component that provides filter data from services.
 * Reads categories from ServiceListService and location from BookingService.
 * Uses platform Filter type for full integration with Filter.Root component.
 *
 * Note: Filter value is accessed via queryOptionsSignal.filter in the service,
 * and Filter.Root manages its own internal state. This component provides
 * the filter options and actions, not the current filter value.
 *
 * @component
 * @example
 * ```tsx
 * <ServiceListFilter.Root>
 *   {({ filterOptions, updateFilter, clearFilters, isFiltered }) => (
 *     <Filter.Root
 *       onChange={updateFilter}
 *       filterOptions={filterOptions}
 *     >
 *       <Filter.FilterOptions>
 *         <Filter.FilterOptionRepeater>
 *           <Filter.FilterOption.Label />
 *           <Filter.FilterOption.SingleFilter />
 *         </Filter.FilterOptionRepeater>
 *       </Filter.FilterOptions>
 *     </Filter.Root>
 *   )}
 * </ServiceListFilter.Root>
 * ```
 */
export function Root(props) {
    const serviceListService = useService(ServiceListServiceDefinition);
    // BookingService location is handled in the service layer via effectiveFilterSignal
    useService(BookingServiceDefinition);
    // Get reactive data from signals
    const filterOptions = serviceListService.filterOptionsSignal.get();
    const isFiltered = serviceListService.isFilteredSignal.get();
    // Pass filter directly to service - location handling is done in service layer
    const updateFilter = (newFilter) => {
        serviceListService.actions.setFilter(newFilter);
    };
    const clearFilters = () => {
        serviceListService.actions.resetFilter();
    };
    const resetFilterField = (fieldName) => {
        serviceListService.actions.resetFilterField(fieldName);
    };
    return props.children({
        filterOptions,
        updateFilter,
        clearFilters,
        resetFilterField,
        isFiltered,
    });
}
